package ring

type RingBuffer struct {
	buf  []int
	head int
	tail int
	size int
}

func (r *RingBuffer) Push(v int) {
	if len(r.buf) == 0 {
		return
	}
	r.buf[r.tail] = v
	r.tail = (r.tail + 1) % len(r.buf)
	r.size++
}

messages.content:
Fix `RingBuffer.Push` in `ring.go`: when the buffer is already full (`r.size == len(r.buf)`), writing at `r.tail` overwrites the oldest element, so `r.head` must advance by 1 mod `len(r.buf)` and `r.size` must stay equal to `len(r.buf)` instead of overflowing past capacity. Reply with ONLY a unified diff in a ```diff block.

```go
package ring

type RingBuffer struct {
	buf  []int
	head int
	tail int
	size int
}

func (r *RingBuffer) Push(v int) {
	if len(r.buf) == 0 {
		return
	}
	r.buf[r.tail] = v
	r.tail = (r.tail + 1) % len(r.buf)
	r.size++
}
```

Fix both bugs in `BinarySearch` in `search.go`: (1) the loop stops when `lo == hi` instead of checking the single remaining element, and (2) `(lo + hi) / 2` can overflow `int` for large indices. Return the fixed `search.go` in a ```go block.

```go
package search

func BinarySearch(nums []int, target int) int {
	lo, hi := 0, len(nums)-1
	for lo < hi {
		mid := (lo + hi) / 2
		if nums[mid] == target {
			return mid
		}
		if nums[mid] < target {
			lo = mid + 1
		} else {
			hi = mid - 1
		}
	}
	return -1
}
```
